package com.example.campsitelottery

import android.content.Context
import com.google.mlkit.vision.barcode.common.Barcode
import com.google.mlkit.vision.codescanner.GmsBarcodeScannerOptions
import com.google.mlkit.vision.codescanner.GmsBarcodeScanning

/**
 * Scans one QR code. Exactly one callback is invoked per scan.
 */
interface QrScanner {

    /**
     * Opens the scanner.
     *
     * @param onScanned receives the text stored in the scanned code.
     * @param onCancelled called if the user closes the scanner without scanning.
     * @param onFailure receives the error if the scanner couldn't be opened.
     */
    fun scan(
        onScanned: (String) -> Unit,
        onCancelled: () -> Unit,
        onFailure: (Exception) -> Unit,
    )
}

/**
 * [QrScanner] that uses Google's code scanner. Google Play services shows the
 * camera screen, so the app doesn't need camera permission.
 *
 * @param context any context; the scanner client is only created when [scan] is called.
 */
class GmsQrScanner(private val context: Context) : QrScanner {

    override fun scan(
        onScanned: (String) -> Unit,
        onCancelled: () -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        val options = GmsBarcodeScannerOptions.Builder()
            .setBarcodeFormats(Barcode.FORMAT_QR_CODE)
            .build()
        GmsBarcodeScanning.getClient(context, options)
            .startScan()
            .addOnSuccessListener { barcode -> onScanned(barcode.rawValue.orEmpty()) }
            .addOnCanceledListener { onCancelled() }
            .addOnFailureListener(onFailure)
    }
}
